// Parse the companies JSON string into individual objects
const companiesString = $input.first().json.companies;
const companies = JSON.parse(companiesString);

return companies.map(company => ({ json: company }));

// Process and structure social media data from all platforms
const results = [];
const errors = [];

for (const item of $input.all()) {
  try {
    const company = item.json.company || 'Unknown';
    const platform = item.json.platform || 'Unknown';

    // Instagram data processing
    if (platform === 'Instagram' && item.json.body) {
      // Extract from HTML or JSON response
      const bodyStr = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body);

      // Look for JSON data in script tags
      const jsonMatch = bodyStr.match(/window\._sharedData = (.*?);<\/script>/);
      if (jsonMatch) {
        const data = JSON.parse(jsonMatch[1]);
        const user = data?.entry_data?.ProfilePage?.[0]?.graphql?.user;

        if (user?.edge_owner_to_timeline_media?.edges) {
          const edges = user.edge_owner_to_timeline_media.edges.slice(0, 10);
          edges.forEach(edge => {
            results.push({
              company: company,
              platform: 'Instagram',
              post_id: edge.node.id,
              caption: edge.node.edge_media_to_caption.edges[0]?.node.text || '',
              image_url: edge.node.display_url,
              likes: edge.node.edge_liked_by.count,
              comments: edge.node.edge_media_to_comment.count,
              timestamp: new Date(edge.node.taken_at_timestamp * 1000).toISOString(),
              url: `https://www.instagram.com/p/${edge.node.shortcode}/`
            });
          });
        } else {
          errors.push(`${company} - Instagram: No posts found or API changed`);
        }
      } else {
        errors.push(`${company} - Instagram: Unable to extract data (consider using Apify)`);
      }
    }

    // Twitter/X data processing
    if (platform === 'Twitter' && item.json.data) {
      const tweets = Array.isArray(item.json.data) ? item.json.data : [item.json.data];
      tweets.forEach(tweet => {
        results.push({
          company: company,
          platform: 'Twitter/X',
          post_id: tweet.id,
          caption: tweet.text,
          likes: tweet.public_metrics?.like_count || 0,
          retweets: tweet.public_metrics?.retweet_count || 0,
          replies: tweet.public_metrics?.reply_count || 0,
          timestamp: tweet.created_at,
          url: `https://twitter.com/${item.json.twitter}/status/${tweet.id}`
        });
      });
    } else if (platform === 'Twitter' && item.json.error) {
      errors.push(`${company} - Twitter: ${item.json.error.message || 'API error'}`);
    }

    // Facebook data processing
    if (platform === 'Facebook' && item.json.data) {
      const posts = Array.isArray(item.json.data) ? item.json.data : [item.json.data];
      posts.forEach(post => {
        results.push({
          company: company,
          platform: 'Facebook',
          post_id: post.id,
          caption: post.message || '(No text)',
          timestamp: post.created_time,
          url: post.permalink_url || `https://www.facebook.com/${item.json.facebook}`
        });
      });
    } else if (platform === 'Facebook' && item.json.error) {
      errors.push(`${company} - Facebook: ${item.json.error.message || 'API error'}`);
    }

  } catch (error) {
    errors.push(`Error processing ${item.json.company || 'unknown'}: ${error.message}`);
  }
}

// Add summary information
const summary = {
  total_posts: results.length,
  errors: errors,
  timestamp: new Date().toISOString(),
  platforms_scraped: [...new Set(results.map(r => r.platform))],
  companies_scraped: [...new Set(results.map(r => r.company))]
};

return [{ json: { summary, posts: results } }];

